`timescale 1ns / 1ps
`default_nettype none

// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md:
//  * READY is a function of state only (holding registers, no skid buffer).
//  * AW and W may arrive in any order; the write fires on the edge that
//    completes the pair.
//  * One outstanding transaction per direction; 1-cycle response latency.
//  * Unmapped (misaligned) addresses answer SLVERR; reads of them return 0.
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
  localparam [1:0]   RESP_OKAY   = 2'b00;
  localparam [1:0]   RESP_SLVERR = 2'b10;

  // ---------------------------------------------------------------------
  // State (control state is reset; holding registers are datapath)
  // ---------------------------------------------------------------------
  reg                  aw_held_q, aw_held_d;
  reg                  w_held_q,  w_held_d;
  reg                  bvalid_q,  bvalid_d;
  reg [1:0]            bresp_q,   bresp_d;
  reg                  rvalid_q,  rvalid_d;
  reg [1:0]            rresp_q,   rresp_d;
  reg [DATA_WIDTH-1:0] rdata_q,   rdata_d;
  reg [DATA_WIDTH-1:0] reg0_q,    reg0_d;
  reg [DATA_WIDTH-1:0] reg1_q,    reg1_d;
  reg [DATA_WIDTH-1:0] reg2_q,    reg2_d;
  reg [DATA_WIDTH-1:0] reg3_q,    reg3_d;

  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;

  // ---------------------------------------------------------------------
  // Handshakes: READY depends on state only
  // ---------------------------------------------------------------------
  assign s_axil_awready = !aw_held_q && !bvalid_q;
  assign s_axil_wready  = !w_held_q && !bvalid_q;
  assign s_axil_arready = !rvalid_q;

  wire aw_hs    = s_axil_awvalid && s_axil_awready;
  wire w_hs     = s_axil_wvalid && s_axil_wready;
  wire ar_hs    = s_axil_arvalid && s_axil_arready;
  wire do_write = (aw_held_q || aw_hs) && (w_held_q || w_hs);

  // Held copy when one exists, else the live bus.
  wire [ADDR_WIDTH-1:0] wr_addr = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held_q ? w_data_q : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held_q ? w_strb_q : s_axil_wstrb;

  // Address decode: mapped when word aligned and within the 16-byte window.
  wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                   ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                   ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

  // Byte-enable mask: byte n is written when wstrb[n] is set.
  wire [DATA_WIDTH-1:0] wr_mask;
  genvar g;
  generate
    for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
      assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
    end
  endgenerate

  // ---------------------------------------------------------------------
  // Read multiplexer
  // ---------------------------------------------------------------------
  reg [DATA_WIDTH-1:0] rd_reg;
  always @* begin
    case (s_axil_araddr[3:2])
      2'd0:    rd_reg = reg0_q;
      2'd1:    rd_reg = reg1_q;
      2'd2:    rd_reg = reg2_q;
      2'd3:    rd_reg = reg3_q;
      default: rd_reg = {DATA_WIDTH{1'b0}};
    endcase
  end

  // ---------------------------------------------------------------------
  // Next-state logic
  // ---------------------------------------------------------------------
  always @* begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    bvalid_d  = bvalid_q;
    bresp_d   = bresp_q;
    rvalid_d  = rvalid_q;
    rresp_d   = rresp_q;
    rdata_d   = rdata_q;
    reg0_d    = reg0_q;
    reg1_d    = reg1_q;
    reg2_d    = reg2_q;
    reg3_d    = reg3_q;

    // Pair write address and write data.
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_hs) aw_held_d = 1'b1;
      if (w_hs)  w_held_d  = 1'b1;
    end

    // Write: register update and write response.
    if (do_write) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_mapped ? RESP_OKAY : RESP_SLVERR;
      if (wr_mapped) begin
        case (wr_addr[3:2])
          2'd0:    reg0_d = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
          2'd1:    reg1_d = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
          2'd2:    reg2_d = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
          2'd3:    reg3_d = (reg3_q & ~wr_mask) | (wr_data & wr_mask);
          default: reg0_d = reg0_q;
        endcase
      end
    end else if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end

    // Read: load the response on AR acceptance, clear when taken.
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rresp_d  = rd_mapped ? RESP_OKAY : RESP_SLVERR;
      rdata_d  = rd_mapped ? rd_reg : {DATA_WIDTH{1'b0}};
    end else if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end
  end

  // ---------------------------------------------------------------------
  // Control and storage registers (synchronous, active-low reset)
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= {DATA_WIDTH{1'b0}};
      reg0_q    <= {DATA_WIDTH{1'b0}};
      reg1_q    <= {DATA_WIDTH{1'b0}};
      reg2_q    <= {DATA_WIDTH{1'b0}};
      reg3_q    <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      reg0_q    <= reg0_d;
      reg1_q    <= reg1_d;
      reg2_q    <= reg2_d;
      reg3_q    <= reg3_d;
    end
  end

  // Holding registers (datapath, not reset; qualified by the held flags).
  always @(posedge aclk) begin
    if (aw_hs) begin
      aw_addr_q <= s_axil_awaddr;
    end
    if (w_hs) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

  // ---------------------------------------------------------------------
  // Outputs
  // ---------------------------------------------------------------------
  assign s_axil_bvalid = bvalid_q;
  assign s_axil_bresp  = bresp_q;
  assign s_axil_rvalid = rvalid_q;
  assign s_axil_rresp  = rresp_q;
  assign s_axil_rdata  = rdata_q;

  // ---------------------------------------------------------------------
  // Design-intent properties (formal only)
  // ---------------------------------------------------------------------
`ifdef FORMAL
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Manager assumptions.
  always @(*) begin
    if (!f_past_valid) assume (!aresetn);
    if (!aresetn) assume (!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);
  end

  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready))
        assume (s_axil_awvalid && $stable(s_axil_awaddr));
      if ($past(s_axil_wvalid && !s_axil_wready))
        assume (s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
      if ($past(s_axil_arvalid && !s_axil_arready))
        assume (s_axil_arvalid && $stable(s_axil_araddr));
    end
  end

  // Subordinate assertions.
  always @(posedge aclk) begin
    if (f_past_valid && !$past(aresetn)) begin
      assert (!s_axil_bvalid && !s_axil_rvalid);
      assert (!aw_held_q && !w_held_q);
    end
    if (f_past_valid && $past(aresetn) && $past(s_axil_bvalid && !s_axil_bready))
      assert (s_axil_bvalid && $stable(s_axil_bresp));
    if (f_past_valid && $past(aresetn) && $past(s_axil_rvalid && !s_axil_rready))
      assert (s_axil_rvalid && $stable(s_axil_rresp) && $stable(s_axil_rdata));
    if (f_past_valid && $past(aresetn))
      assert (s_axil_bvalid == ($past(do_write) || $past(s_axil_bvalid && !s_axil_bready)));
    if (f_past_valid && $past(aresetn))
      assert (s_axil_rvalid == ($past(ar_hs) || $past(s_axil_rvalid && !s_axil_rready)));
  end

  always @(*) begin
    if (f_past_valid) begin
      assert (!(aw_held_q && w_held_q));
      assert (!(bvalid_q && (aw_held_q || w_held_q)));
      assert ((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
      assert ((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
      if (rvalid_q && (rresp_q == RESP_SLVERR))
        assert (rdata_q == {DATA_WIDTH{1'b0}});
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover (s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
      cover (s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
      cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
      cover (s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
