`timescale 1ns / 1ps

// Self-checking testbench for axi4_lite_regs (interface_spec.md section 8).
// Inputs are driven 1 time unit after each rising edge and outputs are
// sampled 1 unit later, well before the next rising edge.

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("check failed at %0t: %s", $time, msg); \
    end \
  end

module axi4_lite_regs_tb;

  localparam [1:0]   OKAY    = 2'b00;
  localparam [1:0]   SLVERR  = 2'b10;
  localparam integer TIMEOUT = 64;

  reg         aclk           = 1'b0;
  reg         aresetn        = 1'b0;
  reg  [3:0]  s_axil_awaddr  = 4'h0;
  reg         s_axil_awvalid = 1'b0;
  wire        s_axil_awready;
  reg  [31:0] s_axil_wdata   = 32'h0;
  reg  [3:0]  s_axil_wstrb   = 4'h0;
  reg         s_axil_wvalid  = 1'b0;
  wire        s_axil_wready;
  wire [1:0]  s_axil_bresp;
  wire        s_axil_bvalid;
  reg         s_axil_bready  = 1'b0;
  reg  [3:0]  s_axil_araddr  = 4'h0;
  reg         s_axil_arvalid = 1'b0;
  wire        s_axil_arready;
  wire [31:0] s_axil_rdata;
  wire [1:0]  s_axil_rresp;
  wire        s_axil_rvalid;
  reg         s_axil_rready  = 1'b0;

  integer        passed = 0;
  integer        failed = 0;
  integer        i;
  reg [8*64-1:0] nonce;
  reg [31:0]     model [0:3];

  axi4_lite_regs #(
      .ADDR_WIDTH(4),
      .DATA_WIDTH(32)
  ) dut (
      .aclk          (aclk),
      .aresetn       (aresetn),
      .s_axil_awaddr (s_axil_awaddr),
      .s_axil_awvalid(s_axil_awvalid),
      .s_axil_awready(s_axil_awready),
      .s_axil_wdata  (s_axil_wdata),
      .s_axil_wstrb  (s_axil_wstrb),
      .s_axil_wvalid (s_axil_wvalid),
      .s_axil_wready (s_axil_wready),
      .s_axil_bresp  (s_axil_bresp),
      .s_axil_bvalid (s_axil_bvalid),
      .s_axil_bready (s_axil_bready),
      .s_axil_araddr (s_axil_araddr),
      .s_axil_arvalid(s_axil_arvalid),
      .s_axil_arready(s_axil_arready),
      .s_axil_rdata  (s_axil_rdata),
      .s_axil_rresp  (s_axil_rresp),
      .s_axil_rvalid (s_axil_rvalid),
      .s_axil_rready (s_axil_rready)
  );

  always #5 aclk = ~aclk;

  // Byte merge used by the reference model.
  function [31:0] merge_tb;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    begin
      merge_tb = old_v;
      if (strb[0]) merge_tb[7:0]   = new_v[7:0];
      if (strb[1]) merge_tb[15:8]  = new_v[15:8];
      if (strb[2]) merge_tb[23:16] = new_v[23:16];
      if (strb[3]) merge_tb[31:24] = new_v[31:24];
    end
  endfunction

  task drive_idle;
    begin
      s_axil_awvalid = 1'b0;
      s_axil_wvalid  = 1'b0;
      s_axil_bready  = 1'b0;
      s_axil_arvalid = 1'b0;
      s_axil_rready  = 1'b0;
    end
  endtask

  // Hold reset for n rising edges; ends 1 unit after an edge.
  task apply_reset;
    input integer n;
    integer k;
    begin
      aresetn = 1'b0;
      drive_idle;
      for (k = 0; k < n; k = k + 1) begin
        @(posedge aclk);
        #1;
      end
      aresetn  = 1'b1;
      model[0] = 32'h0;
      model[1] = 32'h0;
      model[2] = 32'h0;
      model[3] = 32'h0;
      `CHECK(!s_axil_bvalid && !s_axil_rvalid, "BVALID and RVALID low after reset")
      `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high after reset")
    end
  endtask

  // One write and/or one read, with per-channel delays (in cycles) before
  // VALID rises and before BREADY/RREADY rise after the response appears.
  // Must be called 1 unit after a rising edge; returns at the same phase.
  task axi_txn;
    input         do_wr;
    input  [3:0]  waddr;
    input  [31:0] wdat;
    input  [3:0]  wstb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    input         do_rd;
    input  [3:0]  raddr;
    input integer ar_dly;
    input integer r_dly;
    integer    cyc;
    integer    wr_cmp;
    integer    bv_cyc;
    integer    ar_cyc;
    integer    rv_cyc;
    reg        aw_done, w_done, b_done, ar_done, r_done;
    reg        aw_hs, w_hs, b_hs, ar_hs, r_hs;
    reg [1:0]  exp_bresp, exp_rresp, seen_bresp, seen_rresp;
    reg [31:0] exp_rdata, seen_rdata;
    begin
      aw_done    = !do_wr;
      w_done     = !do_wr;
      b_done     = !do_wr;
      ar_done    = !do_rd;
      r_done     = !do_rd;
      cyc        = 0;
      wr_cmp     = -1;
      bv_cyc     = -1;
      ar_cyc     = -1;
      rv_cyc     = -1;
      exp_bresp  = (waddr[1:0] == 2'b00) ? OKAY : SLVERR;
      exp_rresp  = (raddr[1:0] == 2'b00) ? OKAY : SLVERR;
      exp_rdata  = 32'h0;
      seen_bresp = 2'b00;
      seen_rresp = 2'b00;
      seen_rdata = 32'h0;

      while (!(b_done && r_done) && (cyc < TIMEOUT)) begin
        // Drive this cycle.
        s_axil_awaddr  = waddr;
        s_axil_awvalid = !aw_done && (cyc >= aw_dly);
        s_axil_wdata   = wdat;
        s_axil_wstrb   = wstb;
        s_axil_wvalid  = !w_done && (cyc >= w_dly);
        s_axil_bready  = !b_done && ((b_dly == 0) || ((bv_cyc >= 0) && (cyc - bv_cyc >= b_dly)));
        s_axil_araddr  = raddr;
        s_axil_arvalid = !ar_done && (cyc >= ar_dly);
        s_axil_rready  = !r_done && ((r_dly == 0) || ((rv_cyc >= 0) && (cyc - rv_cyc >= r_dly)));
        #1;

        // Sample before the rising edge.
        aw_hs = s_axil_awvalid && s_axil_awready;
        w_hs  = s_axil_wvalid && s_axil_wready;
        b_hs  = s_axil_bvalid && s_axil_bready;
        ar_hs = s_axil_arvalid && s_axil_arready;
        r_hs  = s_axil_rvalid && s_axil_rready;

        // Write response channel.
        if (!do_wr) begin
          `CHECK(!s_axil_bvalid, "no BVALID without a write")
        end else if (b_done) begin
          `CHECK(!s_axil_bvalid, "BVALID cleared after B taken")
        end else begin
          if (bv_cyc < 0) begin
            if (s_axil_bvalid) begin
              bv_cyc     = cyc;
              seen_bresp = s_axil_bresp;
              `CHECK(wr_cmp >= 0, "BVALID only after AW and W accepted")
              `CHECK((wr_cmp >= 0) && (cyc - wr_cmp >= 1) && (cyc - wr_cmp <= 2), "write latency within 2 cycles")
              `CHECK(s_axil_bresp == exp_bresp, "BRESP follows the address policy")
            end
          end else begin
            `CHECK(s_axil_bvalid, "BVALID held until taken")
            `CHECK(s_axil_bresp == seen_bresp, "BRESP stable while stalled")
          end
          if (s_axil_bvalid) begin
            `CHECK(!s_axil_awready && !s_axil_wready, "AWREADY and WREADY low while B pending")
          end
        end

        // Read data channel.
        if (!do_rd) begin
          `CHECK(!s_axil_rvalid, "no RVALID without a read")
        end else if (r_done) begin
          `CHECK(!s_axil_rvalid, "RVALID cleared after R taken")
        end else begin
          if (rv_cyc < 0) begin
            if (s_axil_rvalid) begin
              rv_cyc     = cyc;
              seen_rresp = s_axil_rresp;
              seen_rdata = s_axil_rdata;
              `CHECK(ar_cyc >= 0, "RVALID only after AR accepted")
              `CHECK((ar_cyc >= 0) && (cyc - ar_cyc >= 1) && (cyc - ar_cyc <= 2), "read latency within 2 cycles")
              `CHECK(s_axil_rresp == exp_rresp, "RRESP follows the address policy")
              if (s_axil_rdata !== exp_rdata)
                $display("  read addr %h: rdata %h, expected %h", raddr, s_axil_rdata, exp_rdata);
              `CHECK(s_axil_rdata == exp_rdata, "RDATA matches the register model")
            end
          end else begin
            `CHECK(s_axil_rvalid, "RVALID held until taken")
            `CHECK((s_axil_rresp == seen_rresp) && (s_axil_rdata == seen_rdata), "RRESP and RDATA stable while stalled")
          end
          if (s_axil_rvalid) begin
            `CHECK(!s_axil_arready, "ARREADY low while R pending")
          end
        end

        @(posedge aclk);
        #1;

        // Update the model in edge order: a read accepted on the same edge
        // as a write completes sees the old register value.
        if (ar_hs) begin
          ar_done   = 1'b1;
          ar_cyc    = cyc;
          exp_rdata = (raddr[1:0] == 2'b00) ? model[raddr[3:2]] : 32'h0;
        end
        if (aw_hs) aw_done = 1'b1;
        if (w_hs)  w_done  = 1'b1;
        if (do_wr && aw_done && w_done && (wr_cmp < 0)) begin
          wr_cmp = cyc;
          if (waddr[1:0] == 2'b00)
            model[waddr[3:2]] = merge_tb(model[waddr[3:2]], wdat, wstb);
        end
        if (b_hs) b_done = 1'b1;
        if (r_hs) r_done = 1'b1;
        cyc = cyc + 1;
      end

      `CHECK(b_done && r_done, "transaction completed before timeout")
      drive_idle;
      `CHECK(s_axil_awready && s_axil_wready && s_axil_arready, "READY high the cycle after the response")
    end
  endtask

  task wr;
    input  [3:0]  a;
    input  [31:0] d;
    input  [3:0]  s;
    input integer awd;
    input integer wdl;
    input integer bd;
    begin
      axi_txn(1'b1, a, d, s, awd, wdl, bd, 1'b0, 4'h0, 0, 0);
    end
  endtask

  task rd;
    input  [3:0]  a;
    input integer ard;
    input integer rdl;
    begin
      axi_txn(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ard, rdl);
    end
  endtask

  initial begin
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};

    // Reset and reset values.
    apply_reset(3);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Write then read every register, AW and W together.
    for (i = 0; i < 4; i = i + 1) wr({i[1:0], 2'b00}, 32'hC0DE0000 + i, 4'hF, 0, 0, 0);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Byte enables: partial and empty strobes.
    wr(4'h0, 32'h11223344, 4'b0001, 0, 0, 0);
    rd(4'h0, 0, 0);
    wr(4'h4, 32'hAABBCCDD, 4'b0101, 0, 0, 0);
    rd(4'h4, 0, 0);
    wr(4'h8, 32'h99887766, 4'b1010, 0, 0, 0);
    rd(4'h8, 0, 0);
    wr(4'hC, 32'hFFFFFFFF, 4'b0000, 0, 0, 0);
    rd(4'hC, 0, 0);
    wr(4'hC, 32'h0F0F0F0F, 4'b1100, 0, 0, 0);
    rd(4'hC, 0, 0);

    // AW before W, W before AW, both together after a gap.
    wr(4'h0, 32'h01010101, 4'hF, 0, 3, 0);
    wr(4'h4, 32'h02020202, 4'hF, 1, 0, 0);
    wr(4'h8, 32'h03030303, 4'hF, 4, 0, 0);
    wr(4'hC, 32'h04040404, 4'hF, 2, 2, 0);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // B and R back-pressure.
    wr(4'h4, 32'hBEEF0004, 4'hF, 0, 0, 5);
    rd(4'h4, 0, 6);
    wr(4'h8, 32'hBEEF0008, 4'hF, 2, 0, 3);
    rd(4'h8, 2, 3);

    // Back-to-back transactions.
    for (i = 0; i < 8; i = i + 1) wr({i[1:0], 2'b00}, 32'h0B2B0000 + i, 4'hF, 0, 0, 0);
    for (i = 0; i < 8; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // SLVERR policy: misaligned addresses.
    wr(4'h5, 32'hFFFFFFFF, 4'hF, 0, 0, 0);
    wr(4'hE, 32'hFFFFFFFF, 4'b0011, 0, 2, 1);
    wr(4'h3, 32'hFFFFFFFF, 4'hF, 1, 0, 0);
    rd(4'h5, 0, 0);
    rd(4'hE, 0, 2);
    rd(4'h1, 0, 0);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Reads and writes together.
    axi_txn(1'b1, 4'h8, 32'h12345678, 4'hF, 0, 0, 0, 1'b1, 4'h8, 0, 0);
    rd(4'h8, 0, 0);
    axi_txn(1'b1, 4'h0, 32'hCAFEF00D, 4'hF, 0, 2, 4, 1'b1, 4'h4, 1, 3);
    axi_txn(1'b1, 4'hD, 32'h00000000, 4'hF, 0, 0, 2, 1'b1, 4'h6, 0, 0);
    axi_txn(1'b1, 4'hC, 32'h55AA55AA, 4'b0110, 3, 1, 0, 1'b1, 4'hC, 4, 0);
    axi_txn(1'b1, 4'h4, 32'h0BADF00D, 4'hF, 0, 0, 6, 1'b1, 4'h0, 2, 0);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Reset during traffic: AW accepted without W is discarded.
    s_axil_awaddr  = 4'h4;
    s_axil_awvalid = 1'b1;
    #1;
    `CHECK(s_axil_awready, "AWREADY high while idle")
    @(posedge aclk);
    #1;
    s_axil_awvalid = 1'b0;
    `CHECK(!s_axil_awready && s_axil_wready && !s_axil_bvalid, "AW held while waiting for W")
    apply_reset(1);
    wr(4'h8, 32'h5EED0008, 4'hF, 3, 0, 0);
    rd(4'h4, 0, 0);
    rd(4'h8, 0, 0);

    // Reset during traffic: W accepted without AW is discarded.
    s_axil_wdata  = 32'hDEAD0000;
    s_axil_wstrb  = 4'hF;
    s_axil_wvalid = 1'b1;
    #1;
    `CHECK(s_axil_wready, "WREADY high while idle")
    @(posedge aclk);
    #1;
    s_axil_wvalid = 1'b0;
    `CHECK(s_axil_awready && !s_axil_wready && !s_axil_bvalid, "W held while waiting for AW")
    apply_reset(1);
    wr(4'hC, 32'h5EED000C, 4'hF, 0, 3, 0);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Reset with B and R pending.
    s_axil_awaddr  = 4'h0;
    s_axil_awvalid = 1'b1;
    s_axil_wdata   = 32'hDEADBEEF;
    s_axil_wstrb   = 4'hF;
    s_axil_wvalid  = 1'b1;
    s_axil_araddr  = 4'hC;
    s_axil_arvalid = 1'b1;
    s_axil_bready  = 1'b0;
    s_axil_rready  = 1'b0;
    @(posedge aclk);
    #1;
    s_axil_awvalid = 1'b0;
    s_axil_wvalid  = 1'b0;
    s_axil_arvalid = 1'b0;
    `CHECK(s_axil_bvalid && s_axil_rvalid, "B and R pending before reset")
    apply_reset(2);
    for (i = 0; i < 4; i = i + 1) rd({i[1:0], 2'b00}, 0, 0);

    // Traffic resumes after reset.
    wr(4'h4, 32'hF1F2F3F4, 4'hF, 0, 0, 0);
    rd(4'h4, 0, 0);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

